"""2011-only audited preservation package; no credentials are copied."""
import pathlib,json,csv,hashlib
P=pathlib.Path(__file__).resolve().parent
L=json.loads((P/'S2_2011_RUN_LOG.txt').read_text());Q=json.loads((P/'QA_checks.json').read_text());assert L['exit_code']==0 and all(q['pass'] for q in Q)
def write(n,rows):
 with (P/n).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
