urls={'nov11pub.dat.gz':raw,'nov11nrrep.dat.gz':'https://www2.census.gov/programs-surveys/cps/datasets/2011/supp/nov11nrrep.dat.gz','cpsnov11.pdf':doc,'nrrep.sas':'https://www2.census.gov/programs-surveys/cps/datasets/2011/supp/cps_civeng_nrrepwgt_nov11.sas','person_replicate_instructions.doc':'https://www2.census.gov/programs-surveys/cps/datasets/2018/supp/PERSON-level_Use_of_the_Public_Use_Replicate_Weight_File.doc','variables.json':'https://api.census.gov/data/2011/cps/civic/nov/variables.json','verified_variables.json':'https://api.census.gov/data/2011/cps/civic/nov/variables.json','person_replicate_instructions.txt':'https://www2.census.gov/programs-surveys/cps/datasets/2018/supp/PERSON-level_Use_of_the_Public_Use_Replicate_Weight_File.doc'}
manifest=[{'file':n,'source_url':urls[n],'sha256':v['sha256'],'bytes':v['bytes'],'storage':'official source download manifest' if n.endswith(('.gz','.pdf','.doc')) or n=='variables.json' else 'repository text','retrieved_verified_utc':L['start_utc'],'note':'Person instructions linked from2011 Census page; document dated March7 2012; URL2018 is hosting directory, not inherited2018 variance rule' if n.startswith('person') else 'Official2011 source; credential-free preservation'} for n,v in L['inputs'].items()]
for r in L['api_requests']:manifest.append({'file':'API_'+r['variable']+'.json','source_url':r['url_without_key'],'sha256':r['sha256'],'bytes':r['bytes'],'storage':'repository exact API response','retrieved_verified_utc':r['end_utc'],'note':r['credential_mode']})
write('S2_2011_SOURCE_MANIFEST.csv',manifest)
universe='civilian noninstitutional household age18+;PRSUPINT1;PWNRWGT>0;self/proxy;observed MIS1-8;documentation outgoing-only conflict disclosed'
intro='Next, I will give you a list of types of groups or organizations in which people sometimes participate. (Have you/Has NAME) participated in any of these groups during the last 12 months, that is since November 2010: '
wording=['A school group, neighborhood, or community association such as PTA or neighborhood watch group?','A service or civic organization such as American Legion or Lions Club?','A sports or recreation organization such as a soccer club or tennis club?','A church, synagogue, mosque, or other religious institution or organization, NOT COUNTING (your/his/her) attendance.','Any other type of organization that I have not mentioned?']
md=[]
for j,c in enumerate('ABCDE'):
 md.append({'variable':'PES5'+c,'role':'group_participation','exact_wording':intro+wording[j],'response_codes':'1 Yes;2 No','missing_codes':'-1 NIU;-2 DK;-3 Refused;-9 No Response','universe':universe,'document_edited_universe':('PES3' if j==0 else 'PES5'+chr(ord('a')+j-1))+'=1,2,-2,-3; preserve official released responses; inconsistent upstream PES3 frequency restriction not imposed','weight':'PWNRWGT','raw_position':str(959+2*j)+'-'+str(960+2*j),'source':doc+' Attachment7/8; API uppercase exactname'})
for n,role,pos,coding in [('GESTFIPS','state','93-94','state FIPS;DC11 QA only'),('PEAGE','age','122-123','raw name PEAGE;API exactname PRTAGE;18+'),('HRMIS','rotation','63-64','1-8; raw allgroups; PDF outgoingonly conflict'),('PRPERTYP','civilian','161-162','2 adult civilian;exclude1children/3armedforces'),('PRSUPINT','supplement interview','995-996','1 Interview;2 noninterview'),('PWNRWGT','supplement weight','1007-1016','4 implied decimals;nonresponse;total response group items'),('PWSRWGT','self response weight','997-1006','not used for group items;self-only questions'),('QSTNUM','household merge ID','815-819','replicate file1-5'),('OCCURNUM','person merge ID','820-821','replicate file6-7'),('repwgt0-repwgt160','variance weights','replicate file8-1617','161 weights10characters each;divide10000;0 fullsample;1-160 replicates')]:
 md.append({'variable':n,'role':role,'exact_wording':role,'response_codes':coding,'missing_codes':'not applicable;never impute group missing','universe':universe,'document_edited_universe':'see source; operational eligibility as recorded','weight':'PWNRWGT','raw_position':pos,'source':doc+' Attachment6/7;2011 NRrep SAS;Census person instructions'})
md.append({'variable':'S2_ANY','role':'derived indicator','exact_wording':'1 if any PES5A-E=1;0 only all five=2;otherwise missing','response_codes':'0,1','missing_codes':'otherwise excluded denominator','universe':universe,'document_edited_universe':'Applicable five-item group battery; NIU excluded, never recoded0','weight':'PWNRWGT','raw_position':'derived','source':'official five group types; PES7 leadership is not an additional group category'})
write('S2_2011_MEASUREMENT_DICTIONARY_v1.csv',md)
audit=[('wording','CHANGED','The next questions;Please tell me whether or not;Nov2009-now;religious services attendance','Next I will give you;Have you/Has NAME;sinceNov2010;NOT COUNTING your/his/her attendance','2010/2011 Attachment7/8;2009→2010 wording break not erased,2011 introduction returns toward2009 form'),('organization categories','SAME','five school/community;service/civic;sports/recreation;religious excludingattendance;other','same five types','Religious wording changed; no category added/removed'),('universe','CHANGED','person18+;self/proxy;reporter15+;observedMIS1-8','person18+;self/proxy;reporter18+;observedMIS1-8;PDF saysoutgoingonly','Reporter minimum age changed. Operational raw full8group coverage SAME; formal rotation restriction UNKNOWN because PDF conflicts with releaseddata and officialfrequencies.2009 outgoing→2010 fullsample break persists empirically2011.'),('weight','SAME','PWNRWGT supplement nonresponse','PWNRWGT groupitem suggestedweight;160 NRreplicates now supplied','Same name/purpose; identical calibration not asserted. Availability of official replication changed from2010 unverified.'),('missing codes','SAME','-1 NIU;-2 DK;-3 refused;-9 No Response','same negativecodes','2011 Attachment7/API'),('response codes','SAME','1 Yes;2 No','1 Yes;2 No','2011 Attachment7/API')]
write('S2_2011_2010_CONTINUITY_AUDIT_v1.csv',[{'dimension':a,'status':b,'year_2010':c,'year_2011':d,'evidence':e} for a,b,c,d,e in audit])
write('S2_2011_PROVENANCE_v1.csv',[{'state':r['state'],'state_fips':r['state_fips'],'year':2011,'observation_type':'DIRECT','run_id':L['run_id'],'source':raw,'input_sha256':L['inputs']['nov11pub.dat.gz']['sha256'],'weight':'PWNRWGT','universe':universe,'missing_rule':'any Yes1;allfiveNo0;otherwise excluded','se_method':r['se_method'],'replicate_source':urls['nov11nrrep.dat.gz'],'replicate_sha256':L['inputs']['nov11nrrep.dat.gz']['sha256'],'code_sha256':L['code_sha256'],'output_sha256':L['outputs']['S2_Organizational_Participation_2011_DIRECT_v1.csv']} for r in rows])
text=(P/'codebook.txt').read_text();parts=[]
for a,b in [(365,405),(6037,6191),(6425,6444),(9328,9338),(9978,10007)]:parts.append(f'pdftotext lines{a}-{b}\n'+'\n'.join(text.splitlines()[a-1:b]))
(P/'S2_2011_OFFICIAL_SOURCE_EXCERPTS.txt').write_text('Official source: '+doc+'\nCensus2011 sourcepage: '+page+'\n\n'+'\n\n'.join(parts)+'\n')
qa=['# S2 2011 direct extraction QA','',f'Run: {L["run_id"]}',f'Execution: {L["start_utc"]} — {L["end_utc"]}; exit0.',f'{sum(q["pass"] for q in Q)}/{len(Q)} execution checks PASS;50states exactly;DC storedseparately;SE50/50.','Eligible supplement interviews:81355 (50states+DC);80222 (50states). Classified union valid78553 includingDC,77489 excludingDC;2802 unionmissing includingDC,2733 excludingDC. n_unweighted means classified valid respondents.','', '## Universe limitation and resolution','Official2011 Attachment1/3 says outgoing rotation households only, but the released2011 file contains eligible valid group interviews across MIS1–8. The allgroups sample reproduces the official Attachment13 frequencies exactly and is independently compared with API item weightedtotals. Filtering MIS4/8 would discard valid released supplement interviews and fail those official benchmarks. Canonical operational universe uses age18+,PRPERTYP2,PRSUPINT1 and positivePWNRWGT with all observedrotationgroups. Formal intendedrotationrestriction is UNKNOWN; this document conflict is retained as a harmonization limitation, not silently labelled resolved. Civilian noninstitutional household coverage and age/interview/person eligibility are verified separately.','Self/proxy responses permitted for groupitems;reporter18+ per2011 Attachment3. SelfresponsePWSRWGT is not substituted for totalresponsePWNRWGT. The five group types are retained;PES7 officer/committee service is not a sixth group category.','Attachment7 PES5A edited-universe text lists PES3=1,2,-2,-3 although PES3 frequency codes include1–6; released valid group responses and official frequencies are preserved rather than mechanically applying this inconsistent upstream restriction. Subsequent item missing/NIU responses are not imputed.','', '## SE verification','The official2011 Census downloadpage supplies a NONRESPONSE replicate file and links personreplicate instructions datedMarch7 2012. The hosting URL directory2018 does not define the surveyyear. Exact filehashes and official SAS layout are preserved.161 weightcolumns comprise fullsample0 and160replicates;four implieddecimals. QSTNUM/OCCURNUM one-to-one merge, perpersonrepwgt0=PWNRWGT and all161 publishedweighttotals verified.','For each state and each replicate, compute weightedYes/weightedValid denominator with the same missingmask. SE=sqrt[(4/160)*sum_r(p_r-p_full)^2]. The coefficient is expressly in officialinstructions SAS and agrees with SUDAAN ADJFAY4. Proportions and SE are on0–1scale. No binomial, generalized, S3 or adjacentyear variance formula. Allstate replicate denominatorspositive.','', '## Independent QA and benchmarks','Primary estimates are calculated from fixedwidth officialraw. Five independent Census API tables compare item Yes/No state totals includingDC,510cells;0.51person roundingtolerance. Requests attemptnokey first then environmentkey ifneeded; requests and responses contain no credential. API validates marginals, not directly the union covariance; union is calculated jointly from personraw.','Attachment13 published PES5A frequencycounts exact. Attachment16 national school/sportsYes benchmarks checked with500person publishedroundingtolerance. Publishedpopulation base is basicPWSSWGT adultcivilian control, not canonicalvalidresponse uniondenominator; no denominator substitution. No independent sameyear same-denominator unionbenchmark verified;directestimates retained.','', '## Continuity','WordingCHANGED;categoriesSAME;universeCHANGED(reporter15→18;rotationdocconflictUNKNOWN);weightSAMEname/purpose;missingSAME;responseSAME.2009→2010 wording/universe breaks remain in provenance.2011 referencewording returns toward2009, but no harmonization is imposed. No other year extracted or rerun.','', '## Execution checks','| Check | Result | Evidence |','|---|---|---|']
for q in Q:qa.append('|'+q['name']+'|'+('PASS' if q['pass'] else 'FAIL')+'|'+json.dumps(q['detail'],ensure_ascii=False).replace('|','/')+'|')
qa+=['','## Preservation and stop','Originalbinary sources preserved through exactdownloadURL,bytecount,SHA256manifest;smallmetadata/source excerpts/replicate instructions/SAS/API responses/code are checkedin. Fullraw inputs remain locallyavailable. No Census key in files/logs/repository. No GitHub Actions manually invoked.','STATUS:2011 COMPLETE — STOPPED BEFORE2013.']
(P/'S2_2011_QA_v1.md').write_text('\n'.join(qa)+'\n')
for n,h in L['outputs'].items():assert hashlib.sha256((P/n).read_bytes()).hexdigest()==h
assert hashlib.sha256((P/'extract_2011.py').read_bytes()).hexdigest()==L['code_sha256']
for n,v in L['inputs'].items():assert hashlib.sha256((P/n).read_bytes()).hexdigest()==v['sha256']
names=['S2_Organizational_Participation_2011_DIRECT_v1.csv','S2_2011_QA_v1.md','S2_2011_MEASUREMENT_DICTIONARY_v1.csv','S2_2011_PROVENANCE_v1.csv','S2_2011_2010_CONTINUITY_AUDIT_v1.csv','S2_2011_RUN_LOG.txt','S2_2011_SOURCE_MANIFEST.csv','extract_2011.py','prepare_package.py','verified_variables.json','S2_2011_OFFICIAL_SOURCE_EXCERPTS.txt','S2_2011_DC_QA_v1.csv','S2_2011_ITEM_COUNTS_v1.csv','S2_2011_NATIONAL_QA_v1.csv','S2_2011_REPLICATE_ESTIMATES_v1.csv','QA_checks.json','nrrep.sas','person_replicate_instructions.txt']+['API_PES5'+c+'.json' for c in 'ABCDE']
(P/'SHA256SUMS.txt').write_text(''.join(hashlib.sha256((P/n).read_bytes()).hexdigest()+'  '+n+'\n' for n in names));names+=['SHA256SUMS.txt']
(P/'package_files.json').write_text(json.dumps(names))
